const routes={iheya:{id:'iheya',name:'伊平屋島',ship:'フェリーいへやⅢ',from:'運天港',to:'前泊港',fare:{adult:2580,child:1290},official:'https://www.vill.iheya.okinawa.jp/',changeDeadlineMinutes:60,cancelDeadlineMinutes:60,status:{level:'ok',label:'通常運航',updated:'本日 7:15更新',notice:'本日は通常どおり運航予定です。'},times:[['11:00','12:20'],['15:00','16:20']],inventory:[{passengerCapacity:80,reserved:70,vehicleCapacity:20,vehicles:16},{passengerCapacity:80,reserved:36,vehicleCapacity:20,vehicles:8}]},izena:{id:'izena',name:'伊是名島',ship:'フェリーいぜな尚円',from:'運天港',to:'仲田港',fare:{adult:3500,child:1750},official:'https://www.vill.izena.okinawa.jp/',changeDeadlineMinutes:60,cancelDeadlineMinutes:60,status:{level:'warn',label:'時刻変更',updated:'本日 7:30更新',notice:'第2便は出航時刻を変更するデモ表示です。'},times:[['10:30','11:25'],['15:30','16:25']],inventory:[{passengerCapacity:80,reserved:36,vehicleCapacity:20,vehicles:11},{passengerCapacity:80,reserved:80,vehicleCapacity:20,vehicles:20}]}};
const state={route:null,step:0,trip:'片道',date:new Date(Date.now()+86400000).toISOString().slice(0,10),returnDate:new Date(Date.now()+3*86400000).toISOString().slice(0,10),sailing:0,returnSailing:0,adult:1,child:0,name:'',tel:'',admin:'all'};
const app=document.querySelector('#app'); const yen=n=>n.toLocaleString('ja-JP')+'円';
const ferry=()=>document.querySelector('#ferrymaru').innerHTML;
function status(r){return `<span class="status ${r.status.level}">${r.status.level==='ok'?'✓':r.status.level==='warn'?'△':'!'} ${r.status.label}</span>`} const seats=(r,i)=>r.inventory[i].passengerCapacity-r.inventory[i].reserved;
function home(){document.body.classList.remove('admin-mode');location.hash='user';document.querySelector('.brand-label').textContent='島旅フェリー予約';app.innerHTML=`<section class="screen"><div class="hero"><span class="eyebrow">利用者向け予約サイト</span><h1>フェリーで、<br>島へ行こう。</h1><p>伊平屋島・伊是名島へのフェリーをかんたん予約</p><div class="cloud c1"></div><div class="cloud c2"></div><div class="island i-port">運天港</div><div class="island i-iheya">伊平屋島</div><div class="island i-izena">伊是名島</div><div class="ship-sail">${ferry()}</div><div class="speech">今日はどの島に行く？</div><div class="wave"></div></div><div class="content"><h2 class="section-title">今日はどの島へ行きますか？</h2><div class="route-grid">${Object.values(routes).map(r=>`<article class="route-card"><div class="art">${r.id==='iheya'?'🏝️🌺':'🌴🐚'}</div><p class="route">${r.from} ⇄ ${r.to}</p><h2>${r.name}</h2><p>${r.ship}</p><div class="row">${status(r)}<small>${r.status.updated}</small></div><p><b>次の便 ${r.times[0][0]}</b> → ${r.times[0][1]}</p><button class="primary" data-route="${r.id}">${r.name}を予約する →</button><p><a href="${r.official}" target="_blank">公式の運航情報 ↗</a></p></article>`).join('')}</div><section class="today"><div class="row"><div><small>運航イメージ</small><h2>今日のフェリー</h2></div><span class="status ok">リアルタイム風表示</span></div><div class="timeline"><b>運天港</b><div class="track" style="--ship-pos:${20+new Date().getHours()*2}%"></div><b>島の港</b></div><p class="notice">※ 船の位置は演出用の「運航イメージ」です。AIS等の実位置情報ではありません。運航状況はデモデータです。</p></section></div></section>`;bindHome()}
function bindHome(){document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{state.route=b.dataset.route;state.step=0;booking()})}
const labels=['往復','乗船日','便','人数','乗船者','確認','決済','完了'];
function booking(){const r=routes[state.route];app.innerHTML=`<section class="screen booking-wrap"><div class="booking-head"><div><button class="secondary" data-home>← 島選択</button><h1>${r.name}への予約</h1><p>${r.from} ⇄ ${r.to} ・ ${r.ship}</p></div>${status(r)}</div><div class="stepper" aria-label="予約ステップ">${labels.map((_,i)=>`<i class="${i<=state.step?'on':''}"></i>`).join('')}</div><div class="panel"><small>STEP ${state.step+1} / ${labels.length}</small>${stepContent(r)}</div><p class="footer-note">これは操作体験用プロトタイプです。決済・予約登録・個人情報保存は行いません。</p></section>`;bindBooking(r)}
function stepContent(r){if(state.step===0)return `<h2>往路・復路を選択</h2><p>旅のプランに近いものを選んでね。</p><div class="choice-grid">${['片道','往復'].map(x=>`<button class="choice ${state.trip===x?'selected':''}" data-trip="${x}"><strong>${x==='片道'?'→ 片道':'⇄ 往復'}</strong>${x==='片道'?'島へ向かう便のみ':'帰りの便もまとめて'}</button>`).join('')}</div>${actions()}`;
if(state.step===1)return `<h2>${state.trip==='往復'?'行きと帰り':'行き'}の乗船日を選択</h2><div class="date-grid"><label class="field"><b>行き</b> ${r.from} → ${r.to}<input type="date" id="date" value="${state.date}" min="${new Date().toISOString().slice(0,10)}"></label>${state.trip==='往復'?`<label class="field"><b>帰り</b> ${r.to} → ${r.from}<input type="date" id="return-date" value="${state.returnDate}" min="${state.date}"></label>`:''}</div><div class="notice">${state.trip==='往復'?'帰りの日付は、行きと同じ日または後の日付を選んでください。':''} 季節や天候によりダイヤが変わる場合があります。</div>${actions()}`;
if(state.step===2)return `<h2>${state.trip==='往復'?'行きと帰りの便':'乗る便'}を選択</h2><p class="notice">選択後、決済完了まで座席を仮確保する想定です。旅客席と車両枠は別在庫として管理します。</p><h3 class="direction-title">行き：${r.from} → ${r.to} <small>${state.date}</small></h3><div class="sailings">${sailingCards(r,'outbound')}</div>${state.trip==='往復'?`<h3 class="direction-title return">帰り：${r.to} → ${r.from} <small>${state.returnDate}</small></h3><div class="sailings">${sailingCards(r,'return')}</div>`:''}${actions()}`;
if(state.step===3)return `<h2>人数を選択</h2><div class="controls"><div class="counter"><div><b>大人</b><small> ${yen(r.fare.adult)}</small></div><div><button data-count="adult:-1">−</button> <b>${state.adult}</b> <button data-count="adult:1">＋</button></div></div><div class="counter"><div><b>小人</b><small> ${yen(r.fare.child)}</small></div><div><button data-count="child:-1">−</button> <b>${state.child}</b> <button data-count="child:1">＋</button></div></div><div class="row"><h3>合計</h3><div class="price">${yen(total(r))}</div></div></div>${actions()}`;
if(state.step===4)return `<h2>代表者情報</h2><label class="field">お名前<input id="name" placeholder="島旅 はなこ" value="${state.name}"></label><label class="field">電話番号（デモ）<input id="tel" inputmode="tel" placeholder="090-0000-0000" value="${state.tel}"></label><div class="notice">入力内容は保存・送信されません。</div>${actions()}`;
if(state.step===5)return `<h2>予約内容を確認</h2><div class="summary"><div><span>予約種別</span><b>${state.trip}</b></div><div><span>行き</span><b>${state.date} ${r.times[state.sailing][0]}<br>${r.from} → ${r.to}</b></div>${state.trip==='往復'?`<div><span>帰り</span><b>${state.returnDate} ${r.times[state.returnSailing][0]}<br>${r.to} → ${r.from}</b></div>`:''}<div><span>人数</span><b>大人${state.adult}名・小人${state.child}名</b></div><div><span>代表者</span><b>${state.name||'島旅 はなこ（デモ）'}</b></div><div><span>合計</span><b class="price">${yen(total(r))}</b></div></div>${actions('デモ決済へ')}`;
if(state.step===6)return `<h2>デモ決済</h2><div class="hold-banner"><b>⏱ 座席を仮確保中</b><span>残り 09:42</span></div><div class="pay-demo"><small>DEMO PAYMENT</small><h3>お支払い金額 ${yen(total(r))}</h3><p>カード情報は保存せず、決済事業者へ委譲します。決済失敗時は仮確保を解除する想定です。</p></div>${actions('デモ決済を完了')}`;
return `<div class="ticket"><div class="confetti">${Array.from({length:18},(_,i)=>`<span style="left:${i*6}%;animation-delay:${i%5*.12}s">${i%2?'●':'◆'}</span>`).join('')}</div>${ferry()}<h2>予約できたよ！</h2><p>QRコードを忘れずにね！</p><span class="status ok">✓ QR未使用</span><div class="qr" aria-label="デモQRコード"></div><div class="summary"><div><span>予約種別</span><b>${state.trip}</b></div><div><span>行き</span><b>${state.date} ${r.times[state.sailing][0]}<br>${r.from} → ${r.to}</b></div>${state.trip==='往復'?`<div><span>帰り</span><b>${state.returnDate} ${r.times[state.returnSailing][0]}<br>${r.to} → ${r.from}</b></div>`:''}<div><span>予約番号</span><b>DEMO-${r.id.toUpperCase()}-1029</b></div><div><span>乗船者</span><b>${state.name||'島旅 はなこ'} 様ほか</b></div></div><p class="notice">変更・キャンセルは各便の出航${r.changeDeadlineMinutes}分前まで。欠航時は返金・便変更のお知らせを通知します。</p><h3>この画面を乗船時にご提示ください</h3><button class="secondary" data-change>便を変更</button> <button class="secondary" data-cancel>予約をキャンセル</button></div>`}
function sailingCards(r,direction){const selected=direction==='return'?state.returnSailing:state.sailing;return r.times.map((t,i)=>{const left=seats(r,i),full=left===0,from=direction==='return'?r.to:r.from,to=direction==='return'?r.from:r.to;return `<button class="sailing-card ${selected===i?'selected':''}" data-${direction==='return'?'return-':''}sailing="${i}" ${full?'disabled':''}><span class="status ${full?'bad':left<=10?'warn':'ok'}">${full?'× 満席':left<=10?'△ 残りわずか':'✓ 予約可能'}</span><p><span class="time">${t[0]}</span> ${from}</p><p>↓ 約${r.id==='iheya'?'80':'55'}分</p><p><span class="time">${t[1]}</span> ${to}</p><div class="stock"><b>旅客 残り${left}席</b><small>車両 残り${r.inventory[i].vehicleCapacity-r.inventory[i].vehicles}台</small></div><b>${full?'この便は満席です':selected===i?'✓ この便を選択中':'この便を選ぶ'}</b></button>`}).join('')}
function actions(next='次へ'){return `<div class="actions">${state.step?'<button class="secondary" data-prev>戻る</button>':'<span></span>'}<button class="primary" data-next>${next} →</button></div>`} function total(r){return (state.adult*r.fare.adult+state.child*r.fare.child)*(state.trip==='往復'?2:1)}
function bindBooking(r){document.querySelectorAll('[data-trip]').forEach(x=>x.onclick=()=>{state.trip=x.dataset.trip;booking()});document.querySelectorAll('[data-sailing]').forEach(x=>x.onclick=()=>{state.sailing=+x.dataset.sailing;booking()});document.querySelectorAll('[data-return-sailing]').forEach(x=>x.onclick=()=>{state.returnSailing=+x.dataset.returnSailing;booking()});document.querySelectorAll('[data-count]').forEach(x=>x.onclick=()=>{let[k,v]=x.dataset.count.split(':');state[k]=Math.max(k==='adult'?1:0,state[k]+ +v);booking()});document.querySelector('[data-prev]')?.addEventListener('click',()=>{state.step--;booking()});document.querySelector('[data-next]')?.addEventListener('click',()=>{const outbound=document.querySelector('#date')?.value||state.date;const returning=document.querySelector('#return-date')?.value||state.returnDate;if(state.step===1&&state.trip==='往復'&&returning<outbound){alert('帰りの日付は、行きと同じ日または後の日付を選んでください');return}state.date=outbound;state.returnDate=returning;state.name=document.querySelector('#name')?.value||state.name;state.tel=document.querySelector('#tel')?.value||state.tel;state.step++;booking()});document.querySelector('[data-change]')?.addEventListener('click',()=>{state.step=2;booking()});document.querySelector('[data-cancel]')?.addEventListener('click',()=>{alert('デモ予約をキャンセルしました（実データの変更はありません）');home()});bindGlobal()}
const adminData={all:[86,142,352480,'通常運航'],iheya:[48,81,198240,'通常運航'],izena:[38,61,154240,'時間変更']};
function admin(){document.body.classList.add('admin-mode');location.hash='admin';document.querySelector('.brand-label').textContent='職員管理システム';let d=adminData[state.admin];app.innerHTML=`<section class="screen admin"><div class="admin-identity"><span>🔒 職員専用</span><b>DEMO・権限：システム管理者</b></div><div class="row"><div><small>STAFF CONSOLE</small><h1>運航・予約ダッシュボード</h1><p>両村の予約・乗船・運航情報を一元管理</p></div><button class="secondary" data-home>利用者画面を確認 ↗</button></div><section class="alerts"><div class="row"><h2>⚠ 確認が必要な項目</h2><b>4件</b></div><ul><li class="warn">伊平屋 11:00便が残席10名です</li><li class="bad">欠航便に予約者が48名います（返金・便変更対応）</li><li>運航情報の最終取得：7:30</li><li>決済エラーが3件あります</li></ul></section><div class="admin-tabs">${[['all','すべて'],['iheya','伊平屋'],['izena','伊是名']].map(x=>`<button data-tab="${x[0]}" class="${state.admin===x[0]?'on':''}">${x[1]}</button>`).join('')}</div><div class="metrics">${[['本日の予約',d[0]+'件'],['乗船予定',d[1]+'人'],['売上',yen(d[2])],['運航状況',d[3]]].map(x=>`<article class="metric"><small>${x[0]}</small><b data-number>${x[1]}</b></article>`).join('')}</div><section class="chart-card"><div class="row"><div><small>便別乗船率</small><h2>本日の在庫</h2></div><button class="secondary" data-csv>CSV出力</button></div>${[['伊平屋 11:00',70,80],['伊平屋 15:00',36,80],['伊是名 10:30',36,80],['伊是名 15:30',80,80]].map(x=>`<div class="bar-row"><span>${x[0]}</span><div><i style="width:${x[1]/x[2]*100}%"></i></div><b>${x[1]}/${x[2]}</b></div>`).join('')}</section><div class="table"><h2>便別在庫・運航操作</h2><table><thead><tr><th>航路</th><th>便</th><th>旅客</th><th>車両</th><th>運航状態</th><th>操作</th></tr></thead><tbody><tr><td>伊平屋</td><td>11:00</td><td>70/80</td><td>16/20</td><td><span class="status ok">✓ 通常運航</span></td><td><button class="secondary" data-cancel-sailing>欠航にする</button></td></tr><tr><td>伊是名</td><td>10:30</td><td>36/80</td><td>11/20</td><td><span class="status warn">△ 時刻変更</span></td><td><button class="secondary">編集</button></td></tr><tr><td>伊是名</td><td>15:30</td><td>80/80</td><td>20/20</td><td><span class="status bad">× 満席</span></td><td><button class="secondary">詳細</button></td></tr></tbody></table></div><section class="search-card"><div class="row"><h2>予約検索</h2><button class="secondary" data-search>検索</button></div><div class="filters"><label>予約番号・氏名<input placeholder="DEMO-1042 / 山城"></label><label>航路<select><option>すべて</option><option>伊平屋</option><option>伊是名</option></select></label><label>乗船日<input type="date"></label><label>予約状態<select><option>すべて</option><option>決済済み</option><option>乗船済み</option><option>返金処理中</option><option>ノーショー</option></select></label></div></section><div class="table"><h2>予約一覧</h2><table><thead><tr><th>予約番号</th><th>行き先</th><th>乗船者</th><th>状態</th><th>通知</th><th>操作</th></tr></thead><tbody><tr><td>DEMO-1042</td><td>伊平屋島</td><td>山城様 2名</td><td><span class="status ok">決済済み</span></td><td>予約完了メール</td><td><button class="secondary" data-detail>詳細</button></td></tr><tr><td>DEMO-1041</td><td>伊是名島</td><td>田中様 3名</td><td><span class="status warn">返金処理中</span></td><td>欠航通知済み</td><td><button class="secondary" data-detail>詳細</button></td></tr></tbody></table></div><div class="legend"><b>運航状態：</b><span class="status ok">✓ 通常運航</span><span class="status warn">△ 時刻変更</span><span class="status bad">× 欠航</span><span class="status unknown">? 未確定</span></div></section>`;document.querySelectorAll('[data-tab]').forEach(x=>x.onclick=()=>{state.admin=x.dataset.tab;admin()});document.querySelector('[data-csv]')?.addEventListener('click',()=>alert('デモ：日別・便別・乗船者・売上・キャンセル一覧をCSV出力できます'));document.querySelector('[data-cancel-sailing]')?.addEventListener('click',()=>alert('デモ：予約者48名を表示し、欠航通知 → 返金対象判定 → 返金処理へ進みます'));document.querySelector('[data-search]')?.addEventListener('click',()=>alert('デモ：予約番号・氏名・連絡先・航路・便・状態で絞り込みます'));document.querySelectorAll('[data-detail]').forEach(x=>x.onclick=()=>alert('デモ：乗船者・決済・変更・キャンセル・通知履歴を表示します'));bindGlobal()}
function closeMenu(){const n=document.querySelector('#site-menu'),b=document.querySelector('.menu-toggle');n?.classList.remove('open');b?.setAttribute('aria-expanded','false')}function bindGlobal(){document.querySelectorAll('[data-home]').forEach(x=>x.onclick=()=>{closeMenu();home()});document.querySelectorAll('[data-admin]').forEach(x=>x.onclick=()=>{closeMenu();admin()})}document.querySelector('.menu-toggle')?.addEventListener('click',e=>{const n=document.querySelector('#site-menu'),open=n.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open))});document.addEventListener('click',e=>{if(!e.target.closest('.nav'))closeMenu();if(e.target.closest('[data-admin]'))admin();if(e.target.closest('[data-home]'))home()});window.addEventListener('hashchange',()=>{if(location.hash==='#admin'&&!document.body.classList.contains('admin-mode'))admin();if(location.hash==='#user'&&document.body.classList.contains('admin-mode'))home()});location.hash==='#admin'?admin():home();
